describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(policy.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const policy = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each capped individually at subtotal (1000), so 600+600 = 1200
      expect(policy.computeDiscountCents(1000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps individual negative results to 0", () => {
      const negativeMock = { computeDiscountCents: () => -100 };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // -100 clamped to 0, plus 200 = 200
      expect(policy.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining = 900
      // Second: 10% of 900 = 90, remaining = 810
      // Total discount = 190
      expect(policy.computeDiscountCents(1000)).toBe(190);
    });

    it("stops reducing once remaining reaches 0", () => {
      const policy = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0
      // Total = 1000
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      // Large fixed first, then percentage
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 500 off 1000 → 500 remaining, then 50% of 500 = 250 → total 750
      expect(policyA.computeDiscountCents(1000)).toBe(750);

      // Percentage first, then fixed
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 50% of 1000 = 500, remaining 500, then min(500,500) = 500 → total 1000
      expect(policyB.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("clamps individual negative results to 0 in chain mode", () => {
      const negativeMock = { computeDiscountCents: () => -50 };
      const policy = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative clamped to 0 then min(0,1000)=0; next: min(200,1000)=200
      expect(policy.computeDiscountCents(1000)).toBe(200);
    });
  });

  it("defaults to sum mode", () => {
    const policy = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum: 100 + 200 = 300
    expect(policy.computeDiscountCents(1000)).toBe(300);
  });
});

