describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 500 }],
          5.5,
        ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 500 }],
          -1,
        ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects first bracket at boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // weight = 500g → first bracket (upTo 500)
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5000)).toBe(300);
    });

    it("selects second bracket just above first boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // weight = 501g → second bracket (upTo 1000)
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 5000)).toBe(600);
    });

    it("selects bracket at upper boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // weight = 1000g → second bracket
      expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 5000)).toBe(600);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // weight = 6000g → overflow, defaults to last bracket cost (1200)
      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 5000)).toBe(1200);
    });

    it("uses explicit overflow cost when provided", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2500);
      // weight = 6000g → overflow cost 2500
      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 5000)).toBe(2500);
    });

    it("handles multiple lines with combined weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
      // weight = 300*2 + 200*1 = 800 → second bracket
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    });

    it("zero overflow cost is valid", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 0);
      expect(calc.computeShippingCents([makeLine("a", 99999, 1)], 5000)).toBe(0);
    });
  });
});

