          new FixedAmountDiscountPolicy(800),
        ],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0
      // Total = 1000
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
