+      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 5000)).toBe(600);
+    });
+
+    it("selects bracket at upper boundary", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // weight = 1000g → second bracket
+      expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 5000)).toBe(600);
+    });
+
+    it("uses heaviest bracket cost as overflow default", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // weight = 6000g → overflow, defaults to last bracket cost (1200)
+      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 5000)).toBe(1200);
+    });
+
+    it("uses explicit overflow cost when provided", () => {
+      const calc = new WeightBasedShippingCalculator(brackets, 2500);
+      // weight = 6000g → overflow cost 2500
+      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 5000)).toBe(2500);
+    });
+
+    it("handles multiple lines with combined weight", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
+      // weight = 300*2 + 200*1 = 800 → second bracket
+      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
+    });
+
+    it("sorts brackets regardless of input order", () => {
+      const unordered = [
+        { upToGrams: 5000, costCents: 1200 },
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 1000, costCents: 600 },
+      ];
+      const calc = new WeightBasedShippingCalculator(unordered);
+      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
+    });
+
+    it("zero overflow cost is valid", () => {
+      const calc = new WeightBasedShippingCalculator(brackets, 0);
+      expect(calc.computeShippingCents([makeLine("a", 99999, 1)], 5000)).toBe(0);
+    });
+  });
